@sealed
class LedgerImpl extends RustOpaque implements Ledger {
  // Not to be used by end users
  LedgerImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  LedgerImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_Ledger,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_Ledger,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_LedgerPtr,
  );

  double get balance =>
      RustLib.instance.api.crateApiTotalLedgerBalance(that: this);

  /// `yuan` 是元。返回记账之后的余额，单位也是元。
  double deposit({required double yuan}) =>
      RustLib.instance.api.crateApiTotalLedgerDeposit(that: this, yuan: yuan);

  int get entries =>
      RustLib.instance.api.crateApiTotalLedgerEntries(that: this);

  void reset() => RustLib.instance.api.crateApiTotalLedgerReset(that: this);
}
